# Own-wording feats of Dark Matter (2024 rules), part A: Aberrant Spawn to Intrepid Captain. Shapes follow tvss_feat.py and tee24_feat.py.
# Piloting and Data are Dark Matter skills that the app does not list, so they are carried in notes.
ALSO = []
ASI20 = "Raise %s by 1, to a maximum of 20."
SHIP = "\n**Ship Feat.** Ship feats match the Crew Roles aboard a starship. The DM can grant one to confirm your role or to reward good work in it."
FAC = "\n**Faction Feat.** The DM can grant a Faction feat when you join a faction or finish a quest for it. It can also replace the feat from your background."
UNARMED = "You can use your Dexterity modifier instead of Strength for attack and damage rolls with your Unarmed Strike. When you deal damage with it, you can deal %s damage equal to 1d6 plus your Strength or Dexterity modifier instead of the normal damage."
FEATS = {
 "Aberrant Spawn": {"d": "Species feat for Near-Humans. Advantage against Charm and mind reading, Psychic Resistance, and a tentacle Unarmed Strike.", "pre": "Near-Human",
   "full": "**Aberrant Mind.** You have Advantage on saving throws to avoid or end the Charmed condition and against any effect that would read your thoughts.\n**Psychic Resistance.** You have Resistance to Psychic damage.\n**Tentacle.** One of your limbs is a rubbery tentacle you can strike with. " + UNARMED % "Bludgeoning",
   "fx": {"res": ["Psychic"], "notes": [["Advantage", "Saves to avoid or end Charmed, and against effects that read your thoughts (Aberrant Spawn)"], ["Note", "Aberrant Spawn: tentacle Unarmed Strike uses Dex or Str, 1d6 + mod Bludgeoning"]]}},
 "Ace Pilot": {"d": "Ship feat. Piloting proficiency or Expertise, 1,000 ft move on Evasive Maneuvers, Advantage on ship melee attacks as Pilot.",
   "full": "**Expert Pilot.** You gain proficiency in the Piloting skill. If you already have it, you gain Expertise in it.\n**Hard Turn.** When you take the Evasive Maneuvers action, you can move the ship up to 1,000 feet in any direction.\n**Ramming Maneuver.** As the Pilot, you have Advantage on attack rolls with ship Melee weapons." + SHIP,
   "fx": {"notes": [["Proficiency", "Piloting, or Expertise in it if already proficient (Ace Pilot)"], ["Advantage", "Attack rolls with ship Melee weapons as Pilot (Ace Pilot)"]]}},
 "Adamantine Clan": {"d": "Species feat for Dwarves. Unarmored AC is 10 + Dex + Con (a Shield is allowed). Critical Hits against you become normal hits.", "pre": "Dwarf",
   "full": "**Adamantine Skin.** While you wear no armor, your base Armor Class is 10 plus your Dexterity modifier plus your Constitution modifier. You can still use a Shield and keep this benefit.\n**Adamantine Bones.** Any Critical Hit against you becomes a normal hit.",
   "fx": {"notes": [["Note", "Adamantine Clan: with no armor, AC = 10 + Dex + Con (Shield allowed). Critical Hits against you become normal hits"]]}},
 "Affluent": {"d": "Origin feat. An Uncommon magic item from the DM and 100 CR, plus another 100 CR with each new level.",
   "full": "**Heirloom.** You gain an Uncommon magic item chosen by the DM, handed down in your family. A Bag of Holding or Cloak of Protection is a good fit.\n**Stipend.** You gain 100 CR, and another 100 CR each time you gain a character level after that."},
 "Android": {"d": "Species feat for Near-Humans. No need for food, drink, air or sleep, 4 hour Long Rest, Machine Code language and Technomancy, and a skill.", "pre": "Near-Human",
   "full": "You are an escaped android, almost a perfect copy of a human with wiring hidden under the skin. You may not even know what you are.\n**Construct Anatomy.** You do not need food, drink or air. You do not need to sleep, and magic cannot put you to sleep. You can finish a Long Rest in 4 hours if you spend them motionless and conscious.\n**Machine Code.** You know Machine Code, the language of machines, and the Technomancy cantrip. Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you take the feat).\n**Technical Expertise.** You gain proficiency in Data, Piloting or Technology, your choice.",
   "dm": {"can": ["Technomancy"], "ab": "pick"},
   "fx": {"langs": ["Machine Code"], "notes": [["Proficiency", "One of Data, Piloting or Technology (Android)"], ["Note", "Android: no need for food, drink, air or sleep. Long Rest in 4 hours while motionless"]]}},
 "Aquanaut": {"d": "Species feat for Near-Humans. Breathe underwater, Swim Speed equal to your Speed, and simple talk with swimming creatures.", "pre": "Near-Human",
   "full": "**Aquatic.** You can breathe underwater.\n**Finned.** You have a Swim Speed equal to your Speed.\n**Marine Speech.** You can pass simple ideas to any Beast, Elemental or Monstrosity that has a Swim Speed. It understands your words, but you gain no special ability to understand it.",
   "fx": {"notes": [["Note", "Aquanaut: breathe underwater, Swim Speed equal to your Speed"]]}},
 "Arcane Cannoneer": {"d": "Ship feat. Add Proficiency Bonus to Mega cantrip damage. Once per rest, impose Disadvantage on a save against your Mega spell.",
   "full": "**Mega Cantrip.** When you use the Gunner action to magnify a damaging cantrip to Mega scale, you can add your Proficiency Bonus to its damage roll.\n**Over-Cast.** When you cast a Mega spell that forces a save, you can give one target Disadvantage on the save. After you use this, finish a Short Rest or Long Rest to do so again." + SHIP,
   "lu": {"n": "Over-Cast", "max": 1, "reset": "short"}},
 "Astrogations Inc.: Starguide": {"d": "Faction feat. Once per Long Rest, flip a d20 to its opposite face. 50 percent off Star Charts from Astrogations Inc.",
   "full": "**Momentary Prescience.** When you roll a d20 for a D20 Test, you can flip the die over and use the number on the bottom. On a balanced d20 the top and bottom add up to 21. After you use this, finish a Long Rest to do so again.\n**Navigator's Discount.** You get a 50 percent discount on Star Charts you buy from Astrogations Inc." + FAC,
   "lu": {"n": "Momentary Prescience", "max": 1, "reset": "long"}},
 "Battleframe Dragoon": {"d": "Ship feat. Advantage against Mega creatures once per turn, drop to 1 Mega HP and strike back once per rest, and a path to the Oni rank.",
   "full": "**Kaiju Slayer.** Once on each of your turns, you can gain Advantage on an attack roll against a Mega creature.\n**Relentless Retaliation.** When you are the Pilot of a Battleframe that drops to 0 Mega Hit Points, it can stay at 1 Mega Hit Point instead. You can then make one melee attack with a frame weapon as a Reaction. After you use this, finish a Short Rest or Long Rest to do so again.\n**One Hundred to Oni.** Keep a count of the enemies you reduce to 0 Hit Points. At 100 you earn the rank of Oni and gain the Faction feat Lakshay: Oni." + SHIP,
   "lu": {"n": "Relentless Retaliation", "max": 1, "reset": "short"}, "act": "reaction"},
 "Beastperson": {"d": "Species feat for Near-Humans. Advantage on Dex saves while Bloodied and a claw Unarmed Strike dealing Slashing damage.", "pre": "Near-Human",
   "full": "You may look like any kind of beast, from a cat's ears and tail to something close to a lycanthrope.\n**Animalistic Reflexes.** You have Advantage on Dexterity saving throws while you are Bloodied.\n**Claws.** Your sharp claws are a weapon. " + UNARMED % "Slashing",
   "fx": {"notes": [["Advantage", "Dexterity saves while Bloodied (Beastperson)"], ["Note", "Beastperson: claw Unarmed Strike uses Dex or Str, 1d6 + mod Slashing"]]}},
 "Clown": {"d": "Species feat for Near-Humans. Performance, a reroll of low d20s, and Vicious Mockery that can knock targets Prone.", "pre": "Near-Human",
   "full": "You come from Circus Maximus, where clowns are pale humans with red noses and a love of mischief.\n**Natural Entertainer.** You gain proficiency in Performance.\n**Pratfall.** When you roll a 5 or lower on the d20 for a D20 Test, you can reroll it and must use the new roll. After you use this, finish a Short Rest or Long Rest to do so again.\n**Vicious Shenanigans.** You learn the Vicious Mockery cantrip. Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you take the feat). When a creature fails its save against this spell and rolls a 5 or lower on the d20, it has the Prone condition.",
   "dm": {"can": ["Vicious Mockery"], "ab": "pick"}, "lu": {"n": "Pratfall", "max": 1, "reset": "short"},
   "fx": {"skills": ["Performance"]}},
 "Blaster Master": {"d": "+1 Dex. Bonus damage on matching blaster dice, ignore the DM-C property, and a ranged blaster attack after Dash or Disengage.", "pre": "Level 4+, Dex 13+", "asi": ["DEX"],
   "full": ASI20 % "Dexterity" + "\n**Blaster Roulette.** If two damage dice you roll for a blaster show the same number, you deal bonus damage equal to that number. You can add this bonus only once per turn.\n**Ignore Cooldown.** You ignore the DM-C property of weapons.\n**Run and Gun.** When you take the Dash or Disengage action, you can make a ranged attack with a blaster as a Bonus Action.",
   "act": "bonus"},
 "Brutal Grip": {"d": "+1 Str. Wield a Two-Handed melee weapon in one hand, and a Versatile one in one hand counts as Light.", "pre": "Level 4+, Str 13+", "asi": ["STR"],
   "full": ASI20 % "Strength" + "\n**Heavy Duelist.** You can wield a Melee weapon that has the Two-Handed property in one hand.\n**Versatile Dual Wielder.** While you wield a Melee weapon that has the Versatile property in one hand, it has the Light property for you."},
 "Chief Engineer": {"d": "Ship feat. Technology proficiency or Expertise, stronger Emergency Repairs, and a shield for the Pilot's mental saves.",
   "full": "**Technology Expert.** You gain proficiency in Technology. If you already have it, you gain Expertise in it.\n**Advanced Repairs.** When you take the Emergency Repairs action, you can choose a DC 20 check instead of DC 15. On a success the ship regains an extra 10 Mega Hit Points.\n**Ship Firewall.** While you are the Engineer, the Pilot has Advantage on Intelligence, Wisdom and Charisma saves made on the ship's behalf." + SHIP,
   "fx": {"skills": ["Technology"], "notes": [["Proficiency", "Expertise in Technology if already proficient (Chief Engineer)"]]}},
 "Chronomancy Initiate": {"d": "Learn Moment to Think, add Chronomancy spells to your list, and keep Proficiency Bonus many of them always prepared.", "pre": "Level 4+, Spellcasting", "asi": ["INT", "WIS", "CHA"],
   "full": ASI20 % "Intelligence, Wisdom or Charisma" + "\n**Cantrip.** You learn the Moment to Think cantrip.\n**Expanded Spell List.** Spells with the Chronomancy tag join your spell list. Haste, Slow and Time Stop have that tag.\n**Prepared Spells.** Choose a number of Chronomancy spells equal to your Proficiency Bonus. They are always prepared for you. When you gain a level, you can swap one of them for a different Chronomancy spell.",
   "dm": {"can": ["Moment to Think"], "ab": "asi"}},
 "Church of the Sun Above: Adherent": {"d": "Faction feat. Religion proficiency and an extra 1d8 Radiant damage on a hit, Proficiency Bonus times per Long Rest.",
   "full": "**Dogma.** You gain proficiency in Religion.\n**Solar Judgement.** When you damage a creature with a weapon, a spell or an Unarmed Strike, you can deal an extra 1d8 Radiant damage to it. You can do this a number of times equal to your Proficiency Bonus and regain all uses when you finish a Long Rest." + FAC,
   "lu": {"n": "Solar Judgement", "max": "pb", "reset": "long"}, "fx": {"skills": ["Religion"]}},
 "Creative": {"d": "Origin feat. Heroic Inspiration from a natural 20 on an ability check, and room for two Heroic Inspirations.",
   "full": "**Innovation.** When you roll a 20 on the d20 for an ability check, you gain Heroic Inspiration. After you use this, finish a Short Rest or Long Rest to do so again.\n**Double Inspiration.** You can hold two instances of Heroic Inspiration at once. You can spend only one on each roll.",
   "lu": {"n": "Innovation", "max": 1, "reset": "short"}},
 "Cyberfiend": {"d": "Species feat for Tieflings. Metal claws that deal Necrotic damage, and a 15 foot teleport as a Bonus Action.", "pre": "Tiefling",
   "full": "Your birth was warped by the Foulest Abyss of the mechademons.\n**Cyber Claw.** Retractable metal claws sit in your fingers. " + UNARMED % "Necrotic" + "\n**Translocator.** As a Bonus Action, you can light the circuits under your skin and teleport up to 15 feet to a space you can see. You can do this a number of times equal to your Proficiency Bonus and regain all uses when you finish a Short Rest or Long Rest.",
   "lu": {"n": "Translocator", "max": "pb", "reset": "short", "tag": "Bonus Action"}, "act": "bonus"},
 "DD&D: Artifactor": {"d": "Faction feat. Attune to four magic items, and cast Identify free with an appraisal of the item's value.",
   "full": "You work for DD&D as an Artifactor, finding valuable magic items by sharp dealing or bold expeditions.\n**Additional Attunement.** You can attune to up to four magic items instead of three.\n**Eye for Quality.** You can cast Identify without a spell slot or components. When you do, you also learn the item's market value in Credits." + FAC,
   "dm": {"can": ["Identify"], "ab": "pick"},
   "fx": {"notes": [["Note", "DD&D: Artifactor: attune to up to four magic items"]]}},
 "Demolitionist": {"d": "+1 Str or Dex. Make a free grenade each Long Rest, a better save DC for bombs, and throw a grenade in place of an attack.", "pre": "Level 4+, Str 13+ or Dex 13+", "asi": ["STR", "DEX"],
   "full": ASI20 % "Strength or Dexterity" + "\n**Grenade.** When you finish a Long Rest, you can make one Concussion Grenade, Flashbang or Freeze Bomb. It lasts until your next Long Rest, then falls apart harmlessly.\n**Improved Ordinance.** Your Bomb, Bottled Lightning, Concussion Grenade, Flashbang and Freeze Bomb use this save DC if it is higher: 8 plus the modifier of the ability this feat raised plus your Proficiency Bonus.\n**Quick Grenade.** When you take the Attack action, you can replace one attack with throwing a Concussion Grenade, Flashbang or Freeze Bomb."},
 "Dilettante": {"d": "Species feat for Humans and Near-Humans. Each Long Rest, gain a weapon, skill or tool proficiency, or a Cleric, Druid or Wizard cantrip.", "pre": "Human or Near-Human",
   "full": "When you finish a Long Rest, you gain proficiency in one weapon, skill or tool of your choice, or you temporarily learn one cantrip from the Cleric, Druid or Wizard spell list. Intelligence, Wisdom or Charisma is your spellcasting ability for that cantrip (choose when you take the feat). You keep the proficiency or cantrip until you finish a Long Rest."},
 "Dogfighter": {"d": "Ship feat. Make an attack miss with a Barrel Roll when your Fighter would drop to 0 Mega HP, and Advantage on Targeted Strike.",
   "full": "**Barrel Roll.** When an attack would reduce your ship to 0 Mega Hit Points while you are the Pilot, you can use your Reaction to perform a Barrel Roll, and the attack misses. You can do this only in a Fighter. After you use this, finish a Short Rest or Long Rest to do so again.\n**Precision Strike.** You have Advantage on attack rolls when you take the Targeted Strike action." + SHIP,
   "lu": {"n": "Barrel Roll", "max": 1, "reset": "short", "tag": "Reaction"}, "act": "reaction"},
 "Exomorph": {"d": "Species feat for Skathari. +2 AC at full Hit Points, eat almost anything, and shed your shell to end a condition.", "pre": "Skathari",
   "full": "**Armored Exoskeleton.** While you have all your Hit Points, you gain a +2 bonus to AC.\n**Eat Anything.** You get nourishment from any organic matter. Inorganic matter gives none, but you can eat anything softer than stone without harm.\n**Molt.** As a Bonus Action, you can shed your exoskeleton to remove one or more of these conditions from yourself: Blinded, Deafened, Grappled, Poisoned, Prone or Restrained. After you use this, finish a Long Rest to do so again.",
   "lu": {"n": "Molt", "max": 1, "reset": "long", "tag": "Bonus Action"}, "act": "bonus",
   "fx": {"notes": [["Note", "Exomorph: +2 AC while you have all your Hit Points"]]}},
 "Field Commander": {"d": "+1 Cha. Command an ally within 60 feet to use a Reaction action, and enemies cannot gain Advantage against you next to two allies.", "pre": "Level 4+, Cha 13+", "asi": ["CHA"],
   "full": ASI20 % "Charisma" + "\n**Command.** As an action, you can command an ally within 60 feet that can hear you. The ally immediately takes an action as a Reaction. That action can only be Attack (one attack only), Dash, Dodge, Hide, Influence, Search, Study or Utilize. If the ally takes Dash this way, its benefits last until the end of the ally's next turn.\n**Tight Formation.** While you are within 5 feet of two or more allies who do not have the Incapacitated condition, enemies cannot have Advantage on attack rolls against you."},
 "Flex Caster": {"d": "Spend an extra slot to raise a spell's level by 1, or cast at base level from a higher slot and regain a level 1 slot.", "pre": "Level 4+, Spellcasting", "asi": ["INT", "WIS", "CHA"],
   "full": ASI20 % "Intelligence, Wisdom or Charisma" + "\n**Upcast.** When you cast a spell that can use a higher-level slot, such as Magic Missile, you can spend one additional spell slot to raise its effective level by 1.\n**Downcast.** When you cast a spell with a higher-level slot, you can recycle the extra energy instead of boosting the spell. The spell is cast at its base level and you regain one expended level 1 spell slot."},
 "Focused Critical": {"d": "Weapon attacks and Unarmed Strikes score a Critical Hit on a 19 or 20.", "pre": "Level 4+", "asi": ["STR", "DEX"],
   "full": ASI20 % "Strength or Dexterity" + "\n**Improved Critical.** Your attack rolls with weapons and Unarmed Strikes score a Critical Hit on a 19 or 20 on the d20.",
   "fx": {"notes": [["Note", "Focused Critical: weapon and Unarmed Strike attacks crit on 19-20"]]}},
 "Galactic Bank: Trustee": {"d": "Faction feat. A line of credit that grows with level and 20 percent off items worth 100 CR or less.",
   "full": "You hold the title of Trustee and a Platinum Member account at the Galactic Bank.\n**Line of Credit.** You can spend Credits you lack through a line of credit. It starts at 1,000 CR and rises at character level 5 (10,000 CR), 11 (50,000 CR) and 17 (100,000 CR). Every ten days you go without paying back what you owe, the debt grows by 100 CR.\n**Platinum Member Discounts.** When you buy an item worth 100 CR or less, you get a 20 percent discount." + FAC},
 "Gambler": {"d": "Origin feat. Gaming Set proficiency, Advantage on games of chance, and turn a roll into a 20 after three low rolls in a row.",
   "full": "**Gaming Sets.** You gain proficiency with all Gaming Sets and have Advantage on ability checks for games of chance.\n**Losing Streak.** Record each time you roll a 9 or lower on the d20 for a D20 Test. Roll and record the d20s for Advantage and Disadvantage one after another. After three or more such rolls in a row, you can change a d20 roll to a 20. An attack roll changed this way is not a Critical Hit. Once you use this, discard your recorded rolls.",
   "fx": {"notes": [["Proficiency", "All Gaming Sets (Gambler)"]]}},
 "Grafter": {"d": "Extra Arm and Internal graft slots, a d4 to missed graft weapon attacks, free first installs, and faster Construct graft installs.", "pre": "Level 4+", "asi": ["STR", "DEX", "CON"],
   "full": ASI20 % "Strength, Dexterity or Constitution" + "\n**Extra Slots.** You have two Arm graft slots and two Internal graft slots, and can install a graft in each.\n**Machine Precision.** When you miss with a weapon installed as a graft, such as an Arm Cannon or Embedded Weapon, you can roll 1d4 and add it to the attack roll, which may turn the miss into a hit. You can use this once per turn, a number of times equal to your Proficiency Bonus, and regain all uses when you finish a Long Rest.\n**Painless Attachment.** You lose no Hit Points or Hit Point Dice the first time you install a graft in a given body slot.\n**Quick Installation.** You can install a Construct graft on your body with the Utilize action.",
   "lu": {"n": "Machine Precision", "max": "pb", "reset": "long"}},
 "Grax's Guys for Cheap: Grax's Guy": {"d": "Faction feat. Heroic Inspiration on a natural 1 on a save, plus one skill, one tool and one language.",
   "full": "Grax's Guys are known for being tough and dependable.\n**Plucky.** When you roll a 1 on the d20 for a saving throw, you gain Heroic Inspiration. You cannot use it to reroll that same save.\n**Work Experience.** You gain proficiency in one skill and one tool of your choice, and you learn one language of your choice." + FAC,
   "pick": [{"k": "sk", "t": "skills", "n": 1, "from": ["Acrobatics", "Animal Handling", "Arcana", "Athletics", "Deception", "History", "Insight", "Intimidation", "Investigation", "Medicine", "Nature", "Perception", "Performance", "Persuasion", "Religion", "Sleight of Hand", "Stealth", "Survival"], "title": "skill proficiency"}, {"k": "tl", "t": "tool", "n": 1, "cats": ["art", "music", "game", "other"], "title": "Tool proficiency"}]},
 "Green-Skin": {"d": "Species feat for Near-Humans. Natural armor of 13 + Dex, Advantage against Poisoned, and Poison Resistance.", "pre": "Near-Human",
   "full": "Your people feed on sunlight through tough, photosynthetic skin.\n**Natural Armor.** While you wear no armor, your base Armor Class is 13 plus your Dexterity modifier. You can use a Shield and keep this benefit.\n**Photosynthetic Resilience.** You have Advantage on saving throws to avoid or end the Poisoned condition.\n**Poison Resistance.** You have Resistance to Poison damage.",
   "fx": {"res": ["Poison"], "notes": [["Advantage", "Saves to avoid or end Poisoned (Green-Skin)"], ["Note", "Green-Skin: with no armor, AC = 13 + Dex (Shield allowed)"]]}},
 "Grue": {"d": "Species feat for Near-Humans. Re-hide as a Reaction, Darkvision 120 feet, and self-cast Invisibility in dim light or darkness from level 5.", "pre": "Near-Human",
   "full": "One of your parents was a creature of darkness, such as a shadow. Your skin is black, and you cast a shadow in every direction, even in bright light. In shadows you are nearly invisible.\n**Covert.** When you are hidden and a creature finds you with a successful Wisdom (Perception) check, you can take the Hide action as a Reaction. If your Dexterity (Stealth) roll beats that creature's Wisdom (Perception) check, you silently move and it does not notice you. After you use this, finish a Short Rest or Long Rest to do so again.\n**Darkvision.** You have Darkvision with a range of 120 feet.\n**Swirl of Shadows.** From character level 5, you can cast Invisibility on yourself without a spell slot while you are entirely in Dim Light or Darkness. The spell ends early if you have the Incapacitated condition or end your turn in Bright Light. After you use this, finish a Long Rest to do so again.",
   "lu": {"n": "Covert", "max": 1, "reset": "short", "tag": "Reaction"}, "act": "reaction",
   "dm": {"free": [[5, "Invisibility"]], "ab": "pick"},
   "fx": {"senses": [["Darkvision", 120, ""]]}},
 "Gun-Mage Adept": {"d": "+1 Dex. Martial ranged weapon proficiency, Finger Guns, and Firearm spells always prepared up to your Proficiency Bonus.", "pre": "Level 4+, Spellcasting", "asi": ["DEX"],
   "full": ASI20 % "Dexterity" + "\n**Ranged Weapon Proficiency.** You gain proficiency with Ranged Martial weapons.\n**Cantrip.** You learn the Finger Guns cantrip.\n**Expanded Spell List.** Spells with the Firearm tag join your spell list.\n**Spells Prepared.** Choose a number of Firearm spells equal to your Proficiency Bonus. They are always prepared for you. When you gain a level, you can swap one of them for a different Firearm spell.",
   "dm": {"can": ["Finger Guns"], "ab": "asi"},
   "fx": {"notes": [["Proficiency", "Ranged Martial weapons (Gun-Mage Adept)"]]}},
 "Hacker": {"d": "+1 Int. Data proficiency or Expertise, a built-in Interface Rig, hacking as a Utilize action, and hacking from 60 feet.", "pre": "Level 4+, Int 13+", "asi": ["INT"],
   "full": ASI20 % "Intelligence" + "\n**Black Hat.** You are always treated as having an Interface Rig. Devices also never lock after your hacking attempts.\n**Data Expert.** You gain proficiency in the Data skill. If you already have it, you gain Expertise in it.\n**Quick Hack.** You can try to hack a device with the Utilize action instead of over one minute.\n**Ranged Hack.** You can try to hack Magical Technology you can see within 60 feet of you.",
   "fx": {"notes": [["Proficiency", "Data, or Expertise in it if already proficient (Hacker)"]]}},
 "Heavy Gunner": {"d": "+1 Str. Use Strength for Heavy or Two-Handed ranged weapons, and knock a target Prone on a ranged Critical Hit.", "pre": "Level 4+, Str 13+", "asi": ["STR"],
   "full": ASI20 % "Strength" + "\n**Strong Attacks.** You can use Strength instead of Dexterity for attack and damage rolls with Ranged weapons that have the Heavy or Two-Handed property.\n**Enhanced Critical.** Right after you score a Critical Hit with a Ranged weapon, you can give the target the Prone condition."},
 "Inventor": {"d": "+1 Int. Learn two Gadgeteer Gadgets with no prerequisite, swap one on each level, and use 8 + Int + Proficiency as the save DC.", "pre": "Level 4+, Int 13+", "asi": ["INT"],
   "full": ASI20 % "Intelligence" + "\n**Gadgets.** You gain two Gadgets of your choice from the Gadget Options of the Gadgeteer class. They cannot have a prerequisite, and the Magic Item Gadget is not allowed. When you gain a level, you can swap one of your Gadgets for another one you qualify for. No other creature can use your Gadgets. If you lose one, you can replace it when you finish a Long Rest. If a Gadget requires a saving throw, the DC is 8 plus your Intelligence modifier plus your Proficiency Bonus."},
 "Artillerist": {"d": "Ship feat. Use the mastery of two ship weapon kinds you are proficient with, and ship weapon attacks crit on 19 or 20.",
   "full": "**Ship Weapon Mastery.** You can use the mastery property of two kinds of ship weapons of your choice, provided you are proficient with them. When you finish a Long Rest, you can change which two kinds.\n**Expanded Critical.** Your attack rolls with ship weapons score a Critical Hit on a 19 or 20 on the d20." + SHIP},
 "Industrious": {"d": "Origin feat. A d6 on failed checks with a chosen skill, Proficiency Bonus times per Long Rest, and Advantage against Exhaustion.",
   "full": "**Hardworking.** Choose one skill you are proficient in. Each time you gain a level, you can pick a different skill to replace it. When you fail an ability check with that skill, you can roll a d6 and add it to the roll, which may turn the failure into a success. You can do this a number of times equal to your Proficiency Bonus and regain all uses when you finish a Long Rest.\n**Strong Core.** You have Advantage on saving throws to avoid the Exhaustion condition.",
   "lu": {"n": "Hardworking", "max": "pb", "reset": "long"},
   "fx": {"notes": [["Advantage", "Saves to avoid Exhaustion (Industrious)"]]}},
 "Insectoid": {"d": "Species feat for Near-Humans. Blindsight 10 feet and regrowth of lost body parts in 24 hours.", "pre": "Near-Human",
   "full": "You have a few insect features, such as compound eyes or chitinous plates, and almost always a pair of sensitive antennae.\n**Blindsight.** Your antennae give you Blindsight with a range of 10 feet.\n**Regenerative.** If a body part is amputated and the loss does not kill you, it fully regrows within 24 hours.",
   "fx": {"senses": [["Blindsight", 10, ""]]}},
 "Intrepid Captain": {"d": "Ship feat. A second Captain action as a Bonus Action, crew Immunity to Frightened, and Persuasion proficiency or Expertise.",
   "full": "**All Hands on Deck.** When you take an action from the Captain Crew Role, you can take another action from that role as a Bonus Action. After you use this, finish a Short Rest or Long Rest to do so again.\n**Dauntless Command.** While you are the Captain, the ship's crew have Immunity to the Frightened condition.\n**Galactic Diplomat.** You gain proficiency in Persuasion. If you already have it, you gain Expertise in it." + SHIP,
   "lu": {"n": "All Hands on Deck", "max": 1, "reset": "short"},
   "fx": {"skills": ["Persuasion"], "notes": [["Proficiency", "Expertise in Persuasion if already proficient (Intrepid Captain)"]]}},
}
